[CmdletBinding()]
param(
    [string]$ProjectRoot,
    [switch]$Force
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing

if ([string]::IsNullOrWhiteSpace($ProjectRoot)) { $ProjectRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..')) }
else { $ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot) }

function In([string]$Path) { return (Resolve-Path -LiteralPath (Join-Path $ProjectRoot $Path) -ErrorAction Stop).Path }
function Out([string]$Path) { return [IO.Path]::GetFullPath((Join-Path $ProjectRoot $Path)) }
function C([string]$Hex) { return [Drawing.ColorTranslator]::FromHtml($Hex) }
function F([float]$Size,[Drawing.FontStyle]$Style=[Drawing.FontStyle]::Regular) {
    try { return [Drawing.Font]::new('Segoe UI',$Size,$Style,[Drawing.GraphicsUnit]::Pixel) }
    catch { return [Drawing.Font]::new([Drawing.FontFamily]::GenericSansSerif,$Size,$Style,[Drawing.GraphicsUnit]::Pixel) }
}
function G([Drawing.Graphics]$Graphics) {
    $Graphics.SmoothingMode=[Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $Graphics.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
    $Graphics.PixelOffsetMode=[Drawing.Drawing2D.PixelOffsetMode]::HighQuality
    $Graphics.CompositingQuality=[Drawing.Drawing2D.CompositingQuality]::HighQuality
    $Graphics.TextRenderingHint=[Drawing.Text.TextRenderingHint]::AntiAliasGridFit
}
function Save([Drawing.Image]$Image,[string]$Path) {
    $dir=Split-Path -Parent $Path;if(-not[IO.Directory]::Exists($dir)){[IO.Directory]::CreateDirectory($dir)|Out-Null}
    if([IO.File]::Exists($Path)-and-not$Force){throw "Output exists: $Path. Use -Force."}
    $Image.Save($Path,[Drawing.Imaging.ImageFormat]::Png)
}
function TextBox([Drawing.Graphics]$Graphics,[string]$Text,[Drawing.Font]$Font,[Drawing.Brush]$Brush,[Drawing.RectangleF]$Rect,[Drawing.StringAlignment]$Align=[Drawing.StringAlignment]::Near,[Drawing.StringAlignment]$Line=[Drawing.StringAlignment]::Near) {
    $format=[Drawing.StringFormat]::new();try{$format.Alignment=$Align;$format.LineAlignment=$Line;$format.Trimming=[Drawing.StringTrimming]::EllipsisCharacter;$Graphics.DrawString($Text,$Font,$Brush,$Rect,$format)}finally{$format.Dispose()}
}
function Fit([Drawing.Graphics]$Graphics,[Drawing.Image]$Image,[Drawing.RectangleF]$Bounds) {
    $scale=[Math]::Min($Bounds.Width/$Image.Width,$Bounds.Height/$Image.Height);$w=$Image.Width*$scale;$h=$Image.Height*$scale
    $x=$Bounds.X+($Bounds.Width-$w)/2;$y=$Bounds.Y+($Bounds.Height-$h)/2
    $Graphics.DrawImage($Image,[Drawing.RectangleF]::new($x,$y,$w,$h))
}
function Frame([Drawing.Graphics]$Graphics,[Drawing.Image]$Image,[Drawing.Rectangle]$Bounds,[string]$Title,[string]$Subtitle,[Drawing.Color]$Accent,[Drawing.Font]$TitleFont,[Drawing.Font]$SubFont) {
    $panel=[Drawing.SolidBrush]::new((C '#0E1929'));$border=[Drawing.Pen]::new((C '#2A3B51'),3);$a=[Drawing.SolidBrush]::new($Accent);$white=[Drawing.SolidBrush]::new((C '#F8FAFC'));$muted=[Drawing.SolidBrush]::new((C '#93A4BA'))
    try{$Graphics.FillRectangle($panel,$Bounds);$Graphics.DrawRectangle($border,$Bounds);$Graphics.FillRectangle($a,$Bounds.X,$Bounds.Y,8,$Bounds.Height);TextBox $Graphics $Title $TitleFont $white ([Drawing.RectangleF]::new($Bounds.X+25,$Bounds.Y+18,$Bounds.Width-48,40));TextBox $Graphics $Subtitle $SubFont $muted ([Drawing.RectangleF]::new($Bounds.X+27,$Bounds.Y+62,$Bounds.Width-52,29));Fit $Graphics $Image ([Drawing.RectangleF]::new($Bounds.X+22,$Bounds.Y+100,$Bounds.Width-44,$Bounds.Height-125))}finally{$muted.Dispose();$white.Dispose();$a.Dispose();$border.Dispose();$panel.Dispose()}
}

